export interface LeaveBalance {
  id: number;
  leave_type_code: string;
  leave_type_name: string;
  year: number;
  credited: string;
  availed: string;
  remaining: string;
}

export interface LeaveApplication {
  id: number;
  applicant_id: number;
  leave_type: number;
  leave_type_code: string;
  start_date: string;
  end_date: string;
  number_of_days: string;
  purpose: string;
  station_leave: boolean;
  status: string;
  remarks: string;
  created_at: string;
  substitutes: Array<{
    id: number;
    substitute_id: number;
    duties_description: string;
    accepted: boolean | null;
  }>;
}

export async function fetchLeaveBalances(): Promise<LeaveBalance[]> {
  const res = await fetch("/api/v1/elm/balances/");
  if (!res.ok) throw new Error("Failed to fetch leave balances");
  return res.json();
}

export async function fetchLeaveApplications(): Promise<LeaveApplication[]> {
  const res = await fetch("/api/v1/elm/applications/");
  if (!res.ok) throw new Error("Failed to fetch leave applications");
  return res.json();
}

export async function createLeaveApplication(data: {
  leave_type_code: string;
  start_date: string;
  end_date: string;
  number_of_days: number;
  purpose: string;
  station_leave?: boolean;
  substitute_id?: number;
  substitute_duties?: string;
}): Promise<LeaveApplication> {
  const res = await fetch("/api/v1/elm/applications/", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  });
  if (!res.ok) {
    const err = await res.json();
    throw new Error(err.detail || "Failed to submit leave application");
  }
  return res.json();
}
